'use strict';
const games=[["neon-dodge","Neon Dodge","Action","Dodge debris. Collect stars. Beat your best run.","#7de8ff","Keyboard / touch"],["echo-sequence","Echo Sequence","Memory","Watch the lights. Echo the melody.","#b6a0ff","Tap / click"],["grapple-climb","Grapple Climb","Action","Reel in, swing out, reach the summit.","#ffb671","Keyboard / touch"],["tower-stack","Tower Stack","Timing","A perfect drop. One floor closer to the sky.","#fb97c8","Space / tap"],["tiny-tactics","Tiny Tactics","Strategy","Two actions. Three encounters. Think ahead.","#94d8ff","Keyboard / touch"],["garden-merge","Garden Merge","Puzzle","Merge matching plants into a mighty tree.","#a7e4ab","Arrows / swipe"],["prism-breaker","Prism Breaker","Action","Break radiant bricks. Keep the ball alive.","#ffa9ec","Keyboard / touch"],["rail-switch","Rail Switch","Strategy","Flip junctions. Get every train home.","#ffd488","Tap / click"],["circuit-flip","Circuit Flip","Puzzle","Rotate the wires. Restore the power.","#93e2d7","Tap / click"],["crate-escape","Crate Escape","Puzzle","Ten warehouses. Every crate has a place.","#e6b885","Keyboard / touch"],["gravity-golf","Gravity Golf","Physics","Bend a perfect shot around six worlds.","#a7b1ff","Aim / launch"],["orbit-courier","Orbit Courier","Action","Collect cargo. Outrun orbital patrols.","#a9ecdf","Keyboard / touch"]];
const cards=document.getElementById('cards'),library=document.getElementById('library'),player=document.getElementById('player'),frame=document.getElementById('game-frame');
let active=null,libraryScroll=0;
for(const [i,g] of games.entries()){const a=document.createElement('a');a.className='game-card';a.href='#play/'+g[0];a.style.setProperty('--accent',g[4]);a.setAttribute('aria-label','Play '+g[1]);a.innerHTML='<div class="preview"><img src="previews/'+g[0]+'.jpg" alt="" loading="'+(i<4?'eager':'lazy')+'"><span class="number">'+String(i+1).padStart(2,'0')+'</span></div><div class="card-body"><div class="card-top"><h2>'+g[1]+'</h2><span class="genre">'+g[2]+'</span></div><p class="description">'+g[3]+'</p><div class="card-bottom"><span class="controls">'+g[5]+'</span><span class="play">Play</span></div></div>';cards.append(a)}
function route(){const slug=location.hash.replace(/^#play\//,'');const game=games.find(g=>g[0]===slug);if(!game){const previous=active;active=null;frame.removeAttribute('src');library.hidden=false;player.hidden=true;document.body.classList.remove('playing-game');document.title='Pocket Arcade · Made for Devesh';requestAnimationFrame(()=>{window.scrollTo(0,libraryScroll);if(previous)cards.querySelector('[href="#play/'+previous[0]+'"]').focus({preventScroll:true})});return}if(!active)libraryScroll=window.scrollY;active=game;library.hidden=true;player.hidden=false;document.body.classList.add('playing-game');document.getElementById('game-title').textContent=game[1];document.getElementById('game-control').textContent=game[5]+' · controls inside game';frame.title=game[1]+' game';document.title=game[1]+' · Pocket Arcade';document.getElementById('loading').hidden=false;frame.src='games/'+game[0]+'.html';window.scrollTo(0,0)}
frame.addEventListener('load',()=>{if(!active)return;document.getElementById('loading').hidden=true;try{frame.contentWindow.focus();const target=frame.contentDocument.querySelector('canvas[tabindex]');if(target)target.focus()}catch{frame.focus()}});
document.getElementById('restart').addEventListener('click',()=>{if(active){document.getElementById('loading').hidden=false;frame.src='games/'+active[0]+'.html'}});
document.getElementById('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.getElementById('stage').requestFullscreen();frame.contentWindow.focus()}catch{document.getElementById('fullscreen').textContent='Unavailable'}});
window.addEventListener('hashchange',route);route();

